parameters.functionScript:
// Read the id once: the answer belongs to the record this press was for.
const id = Inputs.recordId;
if (!id) return;
Outputs.idle = false; // the Button ignores presses until the server has answered
try {
  // Added on the server by the amount, so two devices pressing together both count.
  await Noodl.Records.increment(id, { points: 1 }, { className: 'Score' });
  Outputs.added();
} catch (e) {
  Outputs.error = e.message;
  Outputs.failed();
} finally {
  Outputs.idle = true;
}
